svg.script:
(function () {
  var DUR = 8000;

var stEl = document.getElementById('dial-status');
function renderAt(p) {
  if (!stEl) return;
  var lat = Math.round(58 - 18 * Math.abs(Math.sin(Math.PI * p)));
  var label = 'AI & MCP';
  if (p >= 0.16 && p < 0.44) label = 'DATA LAKE';
  else if (p >= 0.44 && p < 0.68) label = 'DISCOVER';
  else if (p >= 0.68 && p < 0.90) label = 'SEARCH';
  var latStr = p < 0.06 || p > 0.94 ? '<60S' : lat + 'S';
  stEl.textContent = 'ACTIVE DETENT  ·  ' + label + '  ·  ' + latStr;
}

  var manual = false;
  window.__seekSvgTime = function (tMs) {
    manual = true;
    renderAt((((tMs / DUR) % 1) + 1) % 1);
  };
  renderAt(0);
  if (typeof requestAnimationFrame === 'function') {
    var t0 = performance.now();
    function loop(now) {
      if (manual) return;
      renderAt(((now - t0) % DUR) / DUR);
      requestAnimationFrame(loop);
    }
    requestAnimationFrame(loop);
  }
})();
